import{_ as a,o as e,c as o,a2 as n}from"./chunks/framework.BfI5QxtK.js";const f=JSON.parse('{"title":"Install Gnoblin","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md"}'),l={name:"installation.md"};function r(s,t,i,d,h,c){return e(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="install-gnoblin" tabindex="-1">Install Gnoblin <a class="header-anchor" href="#install-gnoblin" aria-label="Permalink to &quot;Install Gnoblin&quot;">​</a></h1><p>Gnoblin manages your windows. A separate desktop shell provides the bar, dock and launcher. Install both before your first login.</p><h2 id="choose-your-system" tabindex="-1">Choose your system <a class="header-anchor" href="#choose-your-system" aria-label="Permalink to &quot;Choose your system&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>Install method</th></tr></thead><tbody><tr><td>Fedora</td><td><a href="./install-fedora">Install from COPR</a></td></tr><tr><td>NixOS</td><td><a href="./install-nixos">Add the NixOS module</a></td></tr><tr><td>Arch / CachyOS</td><td><a href="./install-source">Build from source</a></td></tr><tr><td>Debian / Ubuntu</td><td><a href="./install-debian">Install the official package</a></td></tr><tr><td>openSUSE</td><td><a href="./install-source">Build from source</a></td></tr></tbody></table><p>Gnoblin installs alongside GNOME. Your existing GNOME session remains available.</p><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><ol><li><a href="./bring-your-own-shell">Install a desktop shell</a>.</li><li>Log out. At the login screen, choose your user, open the session selector, and choose <strong>Gnoblin</strong>.</li><li>Log in and <a href="./configuration">configure Gnoblin</a>.</li></ol><p>If there is no bar or launcher, right-click the desktop and choose <strong>Open Terminal</strong>. See <a href="./troubleshooting#no-bar-dock-or-launcher">first-login troubleshooting</a>.</p><p>For development builds, see <a href="./install-source">source installation</a>. Release maintainers should use the <a href="./distribution">packaging guide</a>.</p>',9)])])}const b=a(l,[["render",r]]);export{f as __pageData,b as default};
